import time
import rclpy
from rclpy.node import Node
from sensor_msgs.msg import JointState
from trajectory_msgs.msg import JointTrajectory

from omx_ros2.omx_driver import OmxDriver

from omx_interfaces.srv import ExecuteTrajectory, SetGripper


JOINT_NAMES = ['joint1', 'joint2', 'joint3', 'joint4', 'joint5']


class OmxDriverNode(Node):

    def __init__(self):
        super().__init__('omx_driver_node')

        # =========================
        # DRIVER
        # =========================
        self.driver = OmxDriver()
        self.get_logger().info("OmxDriver inicializado e conectado")

        # =========================
        # JOINT STATES
        # =========================
        self.publisher = self.create_publisher(
            JointState,
            'joint_states',
            10
        )

        self.timer = self.create_timer(0.1, self.timer_callback)

        # =========================
        # SERVICES
        # =========================
        self.execute_srv = self.create_service(
            ExecuteTrajectory,
            'execute_trajectory',
            self.execute_trajectory_callback
        )

        self.gripper_srv = self.create_service(
            SetGripper,
            'gripper_control',
            self.set_gripper_callback
        )

        self.get_logger().info("OmxDriverNode pronto")

    # ============================================================
    # JOINT STATES
    # ============================================================

    def timer_callback(self):
        try:
            positions = self.driver.read_joint_positions()
        except Exception as e:
            self.get_logger().error(f"Erro leitura joints: {repr(e)}")
            return

        msg = JointState()
        msg.header.stamp = self.get_clock().now().to_msg()
        msg.name = JOINT_NAMES
        msg.position = list(positions[:5])

        self.publisher.publish(msg)

    # ============================================================
    # EXECUTE TRAJECTORY (SEM ts)
    # ============================================================

    def execute_trajectory_callback(self, request, response):
        try:
            self.get_logger().info(">>> RECEBIDO execute_trajectory")

            traj_msg = request.trajectory

            if not traj_msg.points:
                response.success = False
                response.message = "Trajetória vazia"
                return response

            traj = [
                list(p.positions)
                for p in traj_msg.points
            ]

            self.get_logger().info(
                f"Executando trajetória com {len(traj)} pontos"
            )

            self.driver.execute_trajectory(traj, 0.01)

            response.success = True
            response.message = "OK"

            return response

        except Exception as e:
            self.get_logger().error(f"Erro: {repr(e)}")
            response.success = False
            response.message = str(e)
            return response

    # ============================================================
    # GRIPPER
    # ============================================================

    def set_gripper_callback(self, request, response):
        try:
            pos = float(request.position)

            if pos > 0.5:
                self.get_logger().info("Abrindo gripper")
                self.driver.open_gripper(0.1)
            else:
                self.get_logger().info("Fechando gripper")
                self.driver.close_gripper(0.1)

            response.success = True
            response.message = "OK"

            return response

        except Exception as e:
            self.get_logger().error(f"Erro gripper: {repr(e)}")
            response.success = False
            response.message = str(e)
            return response

    # ============================================================
    # CLEANUP
    # ============================================================

    def __del__(self):
        if hasattr(self, 'driver'):
            self.driver.shutdown()


def main(args=None):
    rclpy.init(args=args)
    node = OmxDriverNode()

    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        rclpy.shutdown()


if __name__ == '__main__':
    main()